import{_ as o,C as n,o as t,c as s,a2 as r,b as d,w as a,a as c,E as l,a3 as h}from"./chunks/framework.Dd_iHz3e.js";const b=JSON.parse('{"title":"14.11 Security Architecture & Zero-Trust Infrastructure","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.11-security-architecture.md","filePath":"system-design/14.11-security-architecture.md"}'),u={name:"system-design/14.11-security-architecture.md"};function p(g,e,m,f,v,k){const i=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=r('<h1 id="_14-11-security-architecture-zero-trust-infrastructure" tabindex="-1">14.11 Security Architecture &amp; Zero-Trust Infrastructure <a class="header-anchor" href="#_14-11-security-architecture-zero-trust-infrastructure" aria-label="Permalink to &quot;14.11 Security Architecture &amp; Zero-Trust Infrastructure&quot;">​</a></h1><h2 id="_1-plain-english-overview" tabindex="-1">1. Plain English Overview <a class="header-anchor" href="#_1-plain-english-overview" aria-label="Permalink to &quot;1. Plain English Overview&quot;">​</a></h2><p>Security architecture establishes end-to-end protective mechanisms across identity verification, transport encryption, privilege separation, and defensive barriers to prevent data breaches, unauthorized device tampering, and infrastructure takeover.</p><hr><h2 id="_2-usage-in-cooking-nexus" tabindex="-1">2. Usage in Cooking Nexus <a class="header-anchor" href="#_2-usage-in-cooking-nexus" aria-label="Permalink to &quot;2. Usage in Cooking Nexus&quot;">​</a></h2><ul><li><strong>Passwordless Identity Tokens</strong>: HMAC-SHA256 signed JSON Web Tokens with strict 15-minute expirations ([controllers/authController.js:L8](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/controllers/authController.js#L8)).</li><li><strong>Data Layer Sanitization</strong>: Mongoose schema projections (<code>.select(&#39;-password&#39;)</code>) preventing credential leakage ([services/memberService.js:L3](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/services/memberService.js#L3)).</li><li><strong>Prompt Injection Defense</strong>: Privileged system instructions in [chef-ai/index.ts:L8-L31](file:///Users/avishjain/avishjain9-repos/26-cooking-nexus/27-kitchen-companion-pro/supabase/functions/chef-ai/index.ts#L8-L31).</li></ul><hr><h2 id="_3-defense-in-depth-security-topology" tabindex="-1">3. Defense-in-Depth Security Topology <a class="header-anchor" href="#_3-defense-in-depth-security-topology" aria-label="Permalink to &quot;3. Defense-in-Depth Security Topology&quot;">​</a></h2>',8)),(t(),d(h,null,{default:a(()=>[l(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20PublicTraffic%5B%22Inbound%20Traffic%20(Browsers%20%26%20IoT%20Cameras)%22%5D%20--%3E%20WAF%5B%22Cloudflare%20Web%20Application%20Firewall%20(WAF)%22%5D%0A%20%20%20%20WAF%20--%3E%7CDDoS%20%26%20Bot%20Mitigation%7C%20TLS%5B%22TLS%201.3%20Termination%22%5D%0A%20%20%20%20TLS%20--%3E%20RateLimiter%5B%22Rate%20Limiting%20%26%20IP%20Reputation%22%5D%0A%20%20%20%20RateLimiter%20--%3E%20AppGateway%5B%22Express%20Gateway%20%2F%20JWT%20Validation%22%5D%0A%20%20%20%20AppGateway%20--%3E%7CLeast%20Privilege%20IAM%7C%20DB%5B(%22MongoDB%20Enterprise%20(Encrypted%20at%20Rest)%22)%5D%0A%0A%20%20%20%20subgraph%20VPC%20%5B%22Private%20VPC%20(Zero-Trust%20Network)%22%5D%0A%20%20%20%20%20%20%20%20AppGateway%0A%20%20%20%20%20%20%20%20DB%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<hr><h2 id="_4-authentication-architecture-comparison" tabindex="-1">4. Authentication Architecture Comparison <a class="header-anchor" href="#_4-authentication-architecture-comparison" aria-label="Permalink to &quot;4. Authentication Architecture Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Auth Pattern</th><th>Credential Storage</th><th>Breach Risk</th><th>Revocation Speed</th><th>Mobile / IoT Fit</th><th>Fit for Cooking Nexus</th></tr></thead><tbody><tr><td><strong>Magic Link JWT (Chosen)</strong></td><td>Ephemeral Signed Token</td><td>Ultra-Low (No stored passwords)</td><td>Fast (15m expiry)</td><td>Frictionless for cooks</td><td>Optimal for consumer MVP</td></tr><tr><td><strong>Password + Argon2</strong></td><td>Hashed &amp; Salted DB field</td><td>High (Credential stuffing)</td><td>Requires password reset</td><td>Cumbersome with messy hands</td><td>Outdated for modern web</td></tr><tr><td><strong>OAuth2 / OIDC (Google/Apple)</strong></td><td>External ID Provider</td><td>Ultra-Low (Delegated)</td><td>Instant via IdP</td><td>Excellent (One-tap biometric)</td><td>Planned next phase</td></tr><tr><td><strong>Stateful Sessions (Redis)</strong></td><td>In-Memory Session ID</td><td>Low</td><td>Instant (Delete session key)</td><td>Requires sticky cookies</td><td>Good, but higher server RAM</td></tr><tr><td><strong>Hardware Mutual TLS (mTLS)</strong></td><td>X.509 Client Certificates</td><td>Zero (Cryptographic hardware)</td><td>Certificate Revocation List</td><td>Mandatory for range cameras</td><td>Production IoT standard</td></tr></tbody></table><hr><h2 id="_5-trade-offs-accepted" tabindex="-1">5. Trade-offs Accepted <a class="header-anchor" href="#_5-trade-offs-accepted" aria-label="Permalink to &quot;5. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Magic Link Email Delay</strong>: Relying on email delivery adds a 5 to 15-second delay compared to typing a password. We accepted this because cooks log in infrequently and benefit from zero password friction.</li></ul><hr><h2 id="_6-what-breaks-first-at-scale" tabindex="-1">6. What Breaks First at Scale? <a class="header-anchor" href="#_6-what-breaks-first-at-scale" aria-label="Permalink to &quot;6. What Breaks First at Scale?&quot;">​</a></h2><ul><li><strong>At 10x</strong>: Storing secrets in plaintext <code>.env</code> files becomes a severe audit risk when onboarding new engineers.</li><li><strong>At 100x</strong>: Token replay attacks: if an attacker intercepts a valid magic link within its 15-minute window, they can authenticate unless the token is single-use invalidated in Redis.</li><li><strong>At 1,000x</strong>: Coordinated bot distributed denial of service targeting the <code>/api/auth/login</code> endpoint.</li></ul><hr><h2 id="_7-senior-engineer-improvements" tabindex="-1">7. Senior Engineer Improvements <a class="header-anchor" href="#_7-senior-engineer-improvements" aria-label="Permalink to &quot;7. Senior Engineer Improvements&quot;">​</a></h2><ol><li><strong>Single-Use JTI Revocation</strong>: Include a unique <code>jti</code> (JWT ID) in every magic link token. Upon first verification, store <code>jti</code> in Redis with a 15-minute TTL; reject any subsequent attempts with the same token ID.</li><li><strong>Secrets Rotation</strong>: Migrate <code>JWT_SECRET</code> and <code>MONGO_URI</code> to <strong>AWS Secrets Manager</strong> with automated 30-day cryptographic key rotation.</li></ol><hr><h2 id="_8-spoken-interview-answer-30-seconds" tabindex="-1">8. Spoken Interview Answer (30 Seconds) <a class="header-anchor" href="#_8-spoken-interview-answer-30-seconds" aria-label="Permalink to &quot;8. Spoken Interview Answer (30 Seconds)&quot;">​</a></h2><p>&quot;Our security architecture follows a zero-trust model. We completely eliminated password vulnerability vectors by using 15-minute single-use signed JWT Magic Links, meaning our database contains zero password hashes to compromise. For IoT hardware, all kitchen optical classification is executed on local camera hardware, sending only abstract JSON hazard metadata to our cloud backend to ensure raw home kitchen video never leaves the premises.&quot;</p>',15))])}const _=o(u,[["render",p]]);export{b as __pageData,_ as default};
